      val r4 = compute_case_freshActive(In_responseCommitment, In_retreatRequestArmed, responseCommitment, retreatRequestArmed, api_defenseCondition, api_qualifiedThreat, api_responseRequest, api_retreatCondition, api_defenseActivation, api_responseRecord, api_retreatNavigationCommand)
      val r5 = compute_case_freshBlocked(In_responseCommitment, In_retreatRequestArmed, responseCommitment, retreatRequestArmed, api_defenseCondition, api_qualifiedThreat, api_responseRequest, api_retreatCondition, api_defenseActivation, api_responseRecord, api_retreatNavigationCommand)
      val r6 = compute_case_defense(In_responseCommitment, In_retreatRequestArmed, responseCommitment, retreatRequestArmed, api_defenseCondition, api_qualifiedThreat, api_responseRequest, api_retreatCondition, api_defenseActivation, api_responseRecord, api_retreatNavigationCommand)
      val r7 = compute_case_observation(In_responseCommitment, In_retreatRequestArmed, responseCommitment, retreatRequestArmed, api_defenseCondition, api_qualifiedThreat, api_responseRequest, api_retreatCondition, api_defenseActivation, api_responseRecord, api_retreatNavigationCommand)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7
    }

